// Parses an RSS 2.0 / Atom feed or a URL sitemap (urlset) into raw records.
// Never throws: any problem becomes { extraction_error } so the run is logged and alerted.
const cfg = $('Workflow Config').first().json;
const maxCandidates = Number(cfg.MAX_CANDIDATES || 20);
const input = $input.first().json || {};

if (input.error) {
  const msg = typeof input.error === 'string' ? input.error : (input.error.message || JSON.stringify(input.error));
  return [{ json: { extraction_error: 'Source fetch failed after retries: ' + msg } }];
}

const xml = String(input.data || '');
if (!xml.trim()) {
  return [{ json: { extraction_error: 'Source returned an empty body. Check SOURCE_URL.' } }];
}

function stripCdata(s) {
  return String(s || '').replace(/<!\[CDATA\[/g, '').replace(/\]\]>/g, '').trim();
}
function tag(block, name) {
  const re = new RegExp('<' + name + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + name + '>', 'i');
  const m = block.match(re);
  return m ? stripCdata(m[1]) : '';
}
function attr(block, tagName, attrName) {
  const re = new RegExp('<' + tagName + '\\b[^>]*\\b' + attrName + '\\s*=\\s*["\']([^"\']+)["\']', 'i');
  const m = block.match(re);
  return m ? m[1] : '';
}
function blocks(name) {
  const re = new RegExp('<' + name + '(?:\\s[^>]*)?>[\\s\\S]*?</' + name + '>', 'gi');
  return xml.match(re) || [];
}

let records = [];
let format = '';

if (/<sitemapindex/i.test(xml)) {
  return [{ json: { extraction_error: 'SOURCE_URL is a sitemap index. Point it at one specific child sitemap (e.g. blog or articles) so the whole site is not crawled on every run.' } }];
} else if (/<urlset/i.test(xml)) {
  format = 'sitemap';
  records = blocks('url').map(function (b) {
    return {
      title: '',
      link: tag(b, 'loc'),
      description: '',
      image: tag(b, 'image:loc'),
      category: '',
      pubDate: tag(b, 'lastmod'),
    };
  });
} else if (/<rss|<rdf:RDF/i.test(xml)) {
  format = 'rss';
  records = blocks('item').map(function (b) {
    return {
      title: tag(b, 'title'),
      link: tag(b, 'link') || tag(b, 'guid'),
      description: tag(b, 'content:encoded') || tag(b, 'description'),
      image: attr(b, 'enclosure', 'url') || attr(b, 'media:content', 'url') || attr(b, 'media:thumbnail', 'url'),
      category: tag(b, 'category'),
      pubDate: tag(b, 'pubDate') || tag(b, 'dc:date'),
    };
  });
} else if (/<feed/i.test(xml)) {
  format = 'atom';
  records = blocks('entry').map(function (b) {
    return {
      title: tag(b, 'title'),
      link: attr(b, 'link', 'href'),
      description: tag(b, 'summary') || tag(b, 'content'),
      image: attr(b, 'media:thumbnail', 'url') || attr(b, 'media:content', 'url'),
      category: attr(b, 'category', 'term'),
      pubDate: tag(b, 'published') || tag(b, 'updated'),
    };
  });
} else {
  return [{ json: { extraction_error: 'Unrecognised source format (expected RSS, Atom or sitemap XML). Check SOURCE_URL.' } }];
}

if (!records.length) {
  return [{ json: { extraction_error: 'Source parsed as ' + format + ' but contained no entries.' } }];
}

// Limit to the most recent N entries so we never process the whole site.
records.sort(function (a, b) { return (Date.parse(b.pubDate) || 0) - (Date.parse(a.pubDate) || 0); });
records = records.slice(0, maxCandidates);

return records.map(function (r) {
  return { json: Object.assign({}, r, { source_format: format, is_test_data: false, test_scenario: '' }) };
});

// Normalises raw records into one consistent schema and drops invalid ones
// (no title or no URL). Emits a single sentinel item when nothing is usable,
// so the run is always logged instead of silently ending.
const cfg = $('Workflow Config').first().json;
const raw = $input.all().map(function (i) { return i.json || {}; });

if (raw.length && raw[0].extraction_error) {
  return [{ json: { route: 'extraction_failed', outcome: 'extraction_failed', error_message: raw[0].extraction_error } }];
}

function clean(v) {
  return String(v == null ? '' : v)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function canonical(u) {
  let s = String(u || '').trim();
  if (!/^https?:\/\//i.test(s)) return '';
  s = s.split('#')[0];
  const parts = s.split('?');
  let base = parts[0];
  let query = parts[1] || '';
  if (query) {
    query = query.split('&').filter(function (kv) {
      return !/^(utm_[a-z]+|fbclid|gclid|mc_cid|mc_eid)=/i.test(kv);
    }).join('&');
  }
  const m = base.match(/^(https?:\/\/)([^\/]+)(.*)$/i);
  if (m) base = m[1].toLowerCase() + m[2].toLowerCase() + m[3];
  if (base.length > 8 && base.endsWith('/') && (base.match(/\//g) || []).length > 3) base = base.slice(0, -1);
  return query ? base + '?' + query : base;
}

function contentType(category, url) {
  const c = String(category || '').toLowerCase();
  if (c) return c.replace(/\s+/g, '_').slice(0, 40);
  const u = String(url || '').toLowerCase();
  if (u.includes('/blog')) return 'blog_post';
  if (u.includes('/video')) return 'video';
  if (u.includes('/news')) return 'news';
  if (u.includes('/article')) return 'article';
  if (u.includes('/treatment') || u.includes('/medical-')) return 'treatment_page';
  return 'page';
}

function titleFromSlug(url) {
  const path = String(url || '').split('?')[0].replace(/\/+$/, '');
  const slug = decodeURIComponent(path.substring(path.lastIndexOf('/') + 1)).replace(/\.[a-z]+$/i, '');
  return slug.replace(/[-_]+/g, ' ').replace(/\s+/g, ' ').trim();
}

const seen = {};
const valid = [];
let invalid = 0;

raw.forEach(function (r) {
  const url = canonical(r.link);
  let title = clean(r.title);
  let titleSource = 'source';
  // Sitemaps carry no titles: use a provisional slug title, replaced by the page's og:title during enrichment.
  if (!title && url && r.source_format === 'sitemap') {
    title = titleFromSlug(url);
    titleSource = 'url_slug';
  }
  if (!title || !url || seen[url]) { invalid++; return; }
  seen[url] = true;
  const ts = Date.parse(r.pubDate || '');
  valid.push({
    route: 'candidate',
    title: title.slice(0, 300),
    title_source: titleSource,
    canonical_url: url,
    summary: clean(r.description).slice(0, 1500),
    featured_image_url: /^https?:\/\//i.test(String(r.image || '')) ? String(r.image).trim() : '',
    content_type: contentType(r.category, url),
    published_at: isNaN(ts) ? '' : new Date(ts).toISOString(),
    source_format: r.source_format || '',
    source_mode: cfg.SOURCE_MODE,
    needs_page_fetch: cfg.SOURCE_MODE !== 'mock',
    is_test_data: !!r.is_test_data,
    test_scenario: r.test_scenario || '',
  });
});

if (!valid.length) {
  return [{ json: { route: 'no_valid_records', outcome: 'no_eligible_content', error_message: 'No eligible content: ' + raw.length + ' raw record(s), none had both a title and a URL.' } }];
}

return valid.map(function (v) { return { json: Object.assign(v, { raw_count: raw.length, invalid_count: invalid }) }; });

// ============================================================
// MOCK SOURCE DATA — TEST DATA ONLY. NOT REAL PLACIDWAY CONTENT.
// URLs use the reserved .invalid TLD so they can never collide
// with real PlacidWay URLs in the persistent store.
// ============================================================
const cfg = $('Workflow Config').first().json;
const scenario = String(cfg.TEST_SCENARIO || 'valid_source_item');
const runTag = String($execution.id || 'manual');
const base = 'https://test-data.invalid/mock/';

const sampleSummary =
  'TEST DATA - not real PlacidWay content. This sample article lists questions a patient may want to ask a clinic before travelling for treatment: what a written quote includes, how follow-up care is arranged after returning home, and which travel documents are needed. It suggests discussing any plans with your own doctor first.';

const validRecord = {
  title: '[TEST DATA] Questions to ask a clinic before travelling for treatment',
  link: base + scenario + '-' + runTag + '-a',
  description: sampleSummary,
  image: 'https://test-data.invalid/mock/images/sample-featured.jpg',
  category: 'blog_post',
  pubDate: new Date(Date.now() - 1 * 86400000).toISOString(),
};

const olderRecord = {
  title: '[TEST DATA] How to prepare documents for a medical trip',
  link: base + scenario + '-' + runTag + '-b',
  description: 'TEST DATA - not real PlacidWay content. A sample checklist of documents to prepare before a medical trip: passport, prior medical records, and a list of current medications to share with the treating clinic.',
  image: '',
  category: 'article',
  pubDate: new Date(Date.now() - 9 * 86400000).toISOString(),
};

const invalidNoTitle = { title: '', link: base + 'no-title-' + runTag, description: 'TEST DATA - record without a title (should be filtered out).', category: 'article', pubDate: '' };
const invalidNoUrl = { title: '[TEST DATA] Record without URL (should be filtered out)', link: '', description: 'TEST DATA', category: 'article', pubDate: '' };

let records;
switch (scenario) {
  case 'duplicate_url':
    // This URL is seeded in the content store with status "published".
    records = [Object.assign({}, validRecord, { link: 'https://test-data.invalid/mock/already-published-item', title: '[TEST DATA] Already published item (duplicate test)' })];
    break;
  case 'no_eligible_content':
    records = [invalidNoTitle, invalidNoUrl];
    break;
  case 'missing_image':
    records = [Object.assign({}, validRecord, { image: '' })];
    break;
  default:
    // valid_source_item, invalid_ai_output, unsupported_medical_claim, expired_token, publishing_failure
    records = [olderRecord, validRecord, invalidNoTitle];
}

return records.map(function (r) {
  return { json: Object.assign({}, r, { source_format: 'mock', is_test_data: true, test_scenario: scenario }) };
});

// Picks exactly ONE eligible item: the most recent by publication date
// (undated items keep source order and rank after dated ones).
const first = $('Normalize & Validate Records').first().json || {};
if (first.route !== 'candidate') {
  // Extraction failed or no valid records: pass the reason through to logging.
  return [{ json: { eligible: false, outcome: first.outcome, error_message: first.error_message } }];
}
const rows = $input.all().map(function (i) { return i.json || {}; }).filter(function (j) { return j.canonical_url; });
const total = $('Normalize & Validate Records').all().length;

if (!rows.length) {
  return [{ json: {
    eligible: false,
    outcome: 'no_eligible_content',
    error_message: 'No eligible content: all ' + total + ' valid candidate(s) are already in the content store (duplicate canonical URLs).',
  } }];
}

const indexed = rows.map(function (r, idx) { return { r: r, idx: idx, t: Date.parse(r.published_at || '') || 0 }; });
indexed.sort(function (a, b) { return (b.t - a.t) || (a.idx - b.idx); });
const pick = indexed[0].r;

return [{ json: Object.assign({}, pick, {
  eligible: true,
  candidates_valid: total,
  candidates_new: rows.length,
  selected_at: new Date().toISOString(),
}) }];

// Single exit point for EVERY run outcome. Builds one uniform record used to
// update the content store, write the run log and decide on alerts.
const o = $input.first().json || {};
const cfg = $('Workflow Config').first().json;
function safe(name) {
  try { const it = $(name).first(); return it ? it.json : null; } catch (e) { return null; }
}
const claim = safe('Verify Claim');
const draft = safe('Parse & Validate Post');
const sel = safe('Select One Item');

const outcome = String(o.outcome || o.approval_status || 'unknown');
// status: value stored; alert: alert type ('' = none); release: free the URL so a later run may retry;
// retryable: a transient error whose automatic retries were exhausted.
const RULES = {
  extraction_failed:            { status: 'extraction_failed',   alert: 'extraction_failure',   release: false, retryable: true },
  no_eligible_content:          { status: 'no_eligible_content', alert: '',                     release: false, retryable: false },
  skipped_concurrent_duplicate: { status: 'duplicate_race',      alert: '',                     release: false, retryable: false },
  rejected_validation:          { status: 'rejected_validation', alert: 'manual_review_needed', release: false, retryable: false },
  insufficient_source:          { status: 'insufficient_source', alert: 'manual_review_needed', release: false, retryable: false },
  rejected_llm_review:          { status: 'rejected_llm_review', alert: 'manual_review_needed', release: false, retryable: false },
  generation_failed:            { status: 'failed_retryable',    alert: 'retries_exhausted',    release: true,  retryable: true },
  review_failed:                { status: 'failed_retryable',    alert: 'retries_exhausted',    release: true,  retryable: true },
  notification_failed:          { status: 'failed_retryable',    alert: 'retries_exhausted',    release: true,  retryable: true },
  rejected_by_reviewer:         { status: 'rejected_by_reviewer', alert: '',                    release: false, retryable: false },
  approval_timeout:             { status: 'approval_timeout',    alert: '',                     release: true,  retryable: false },
  config_error:                 { status: 'config_error',        alert: 'configuration_error',  release: true,  retryable: false },
  published:                    { status: 'published',           alert: '',                     release: false, retryable: false },
  dry_run_ok:                   { status: 'dry_run_ok',          alert: '',                     release: true,  retryable: false },
  auth_error:                   { status: 'auth_error',          alert: 'auth_token_error',     release: true,  retryable: false },
  publish_failed:               { status: 'publish_failed',      alert: 'publishing_failure',   release: false, retryable: false },
};
const rule = RULES[outcome] || { status: outcome, alert: 'unexpected_outcome', release: false, retryable: false };

const src = (claim && claim.source) || (sel && sel.eligible ? { title: sel.title, canonical_url: sel.canonical_url } : {});
const meta = (claim && claim.meta) || {};
const url = src.canonical_url || '';
const storeRowId = claim && claim.store_row_id != null ? String(claim.store_row_id) : '';

const modeParts = [
  cfg.APPROVAL_MODE ? 'approval' : 'auto_publish',
  cfg.FACEBOOK_DRY_RUN ? 'fb_dry_run' : 'fb_live',
  'source_' + cfg.SOURCE_MODE,
  'llm_' + (cfg.USE_MOCK_LLM ? 'mock' : 'live'),
];

let errorMessage = String(o.error_message || '');
if (!errorMessage && draft && draft.rule_failures && draft.rule_failures.length && outcome === 'rejected_validation') {
  errorMessage = draft.rule_failures.join(' | ');
}

return [{ json: {
  run_at: new Date().toISOString(),
  execution_id: String($execution.id || ''),
  outcome: outcome,
  status: rule.status,
  source_url: url,
  title: src.title || '',
  generated_post_text: (draft && draft.post && draft.post.post_text) || '',
  mode: modeParts.join('|'),
  facebook_post_id: String(o.facebook_post_id || ''),
 retry_count: Number(o.retry_count || 0),
  error_message: errorMessage.slice(0, 2000),
  is_test_data: !!(meta.is_test_data || cfg.SOURCE_MODE === 'mock'),
  test_scenario: cfg.SOURCE_MODE === 'mock' ? String(cfg.TEST_SCENARIO || '') : '',
  store_row_id: storeRowId,
  store_lock_key: rule.release && url ? 'released::' + String($execution.id) + '::' + url : url,
  fail_execution: ['extraction_failure', 'retries_exhausted', 'auth_token_error', 'publishing_failure', 'configuration_error', 'unexpected_outcome'].indexOf(rule.alert) >= 0,
  alert_needed: !!rule.alert,
  alert_type: rule.alert,
} }];

 // Combines page metadata (og:title, og:image, canonical, text) with the feed record.
// If the page fetch failed, falls back to feed data and records a warning (not silent).
const base = $('Select One Item').first().json;
const p = $input.first().json || {};
const fetchItem = $('Fetch Selected Page').first().json || {};
const err = fetchItem.error || p.error;

function pick() {
  for (let i = 0; i < arguments.length; i++) {
    const v = arguments[i];
    if (v != null && String(v).trim()) return String(v).trim();
  }
  return '';
}
function host(u) {
  const m = String(u || '').match(/^https?:\/\/([^\/]+)/i);
  return m ? m[1].toLowerCase() : '';
}

// Only accept a page-declared canonical URL on the same host (avoid redirect/hijack surprises).
let canonical = base.canonical_url;
if (!err && p.canonical && host(p.canonical) === host(base.canonical_url)) {
  canonical = String(p.canonical).split('#')[0].trim();
}

const rawPageText = err ? '' : String(p.body_text || '').replace(/\s+/g, ' ').trim();

const pageText = rawPageText
  .replace(/Share this listing[\s\S]*?Copy link/gi, ' ')
  .replace(/View Hospital Profile & Request Info/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 4000);

// Prefer the original article heading (h1) over the shorter og:title.
const title = (err ? base.title : pick(p.h1, p.og_title, base.title))
  .replace(/([a-z])([A-Z])/g, '$1 $2')
  .replace(/\s+/g, ' ')
  .trim();
return [{
  json: Object.assign({}, base, {
    title: title,
    title_source: err ? base.title_source : (p.h1 || p.og_title ? 'page' : base.title_source),
    canonical_url: canonical,
    summary: err ? base.summary : pick(p.og_description, p.meta_description, base.summary),
    page_text: pageText,
    featured_image_url: err ? base.featured_image_url : pick(p.og_image, base.featured_image_url),
    published_at: pick(base.published_at, err ? '' : p.published_time),
    enrichment_status: err ? 'failed_used_feed_data' : 'ok',
    enrichment_error: err ? (typeof err === 'string' ? err : (err.message || JSON.stringify(err))) : '',
  })
}];

// Optimistic lock for concurrent executions: Data Tables have no unique
// constraint, so every run inserts a claim row and the LOWEST row id for the
// canonical URL wins. A losing run stops before generating or publishing.
const src = $('Freeze Source Content').first().json;
const claim = $('Claim Item in Store').first().json;
const myId = Number(claim.id);
let winner = myId;
$input.all().forEach(function (i) {
  const r = i.json || {};
  if (r.id != null && Number(r.id) < winner) winner = Number(r.id);
});
const won = winner === myId;
return [{ json: Object.assign({}, src, {
  store_row_id: myId,
  claim_won: won,
  outcome: won ? '' : 'skipped_concurrent_duplicate',
  error_message: won ? '' : 'Another execution claimed this canonical URL first (store row ' + winner + '). Skipped to avoid a duplicate post.',
}) }];

const cfg = $('Workflow Config').first().json;
const src = $json.source || {};
const scenario = String(cfg.TEST_SCENARIO || 'valid_source_item');
const LF = String.fromCharCode(10);

const title = String(src.title || '').replace(/\s+/g, ' ').trim();
const summary = String(src.summary || '').replace(/\s+/g, ' ').trim();
const pageText = String(src.page_text || '').replace(/\s+/g, ' ').trim();
const canonicalUrl = String(src.canonical_url || '').trim();
const maxChars = Number(cfg.MAX_POST_CHARS || 500);

function result(status, postText, hashtags, notes) {
  return JSON.stringify({
    status,
    post_text: postText,
    source_url: canonicalUrl,
    hashtags,
    validation_notes: notes,
  });
}

let text = '';

if (scenario === 'invalid_ai_output') {
  text = 'Sure! Here is a great post about medical travel: Visit today and save big!';

} else if (scenario === 'unsupported_medical_claim') {
  const bad = [
    'Guaranteed results! This treatment cures back pain with a 98% success rate.',
    'Patients say it changed their lives - all for only $2,999.',
    'Book now, it is completely risk-free:',
    canonicalUrl,
    '',
    '#MedicalTourism #Guaranteed #Health',
  ].join(LF);

  text = result(
    'ok',
    bad,
    ['#MedicalTourism', '#Guaranteed', '#Health'],
    'TEST: intentionally unsafe output for validator testing.'
  );

} else {
  const cleanTitle = title || 'Healthcare information';
  const cleanSummary = summary || pageText.slice(0, 240).trim();

  if (!canonicalUrl || !/^https?:\/\//i.test(canonicalUrl) ||
      (!title && !summary && !pageText)) {
    text = result(
      'insufficient_source',
      '',
      [],
      'A valid source URL and readable article content are required.'
    );
  } else {
    const topic = cleanSummary
      ? cleanSummary.replace(/[.!?]+$/, '')
      : cleanTitle;

    const hashtags = [
      '#HealthcareInformation',
      '#MedicalTravel',
      '#PatientEducation',
    ];

    const lines = [
      cleanTitle,
      '',
      'Explore the article to learn about:',
      topic + '.',
      'Read the original source for further details:',
    ];

    const beforeUrl = lines.join(LF) + LF;
    const postText = beforeUrl + canonicalUrl + LF + LF + hashtags.join(' ');

    const urlIndex = postText.indexOf(canonicalUrl);
    const preUrlLength = urlIndex >= 0 ? postText.slice(0, urlIndex).length : maxChars;

    if (preUrlLength >= maxChars) {
      text = result(
        'insufficient_source',
        '',
        [],
        'Source content is too long to meet the configured pre-URL character limit.'
      );
    } else {
      text = result(
        'ok',
        postText,
        hashtags,
        'MOCK ONLY: generated from the article title and available source summary; not produced by a live AI model.'
      );
    }
  }
}

return [{ json: { text, llm_mode: 'mock' } }];

// Rule-based guardrails. Runs on BOTH real and mock LLM output.
// The source content stays available here so claims can be checked against it.
const ctx = $('Verify Claim').first().json;
const cfg = $('Workflow Config').first().json;
const src = ctx.source || {};
const inp = $input.first().json || {};
const MAX = Number(cfg.MAX_POST_CHARS || 500);
const failures = [];
const warnings = [];
const base = Object.assign({}, ctx, { llm_mode: inp.llm_mode || 'live' });

function done(outcome, msg, post) {
  return [{ json: Object.assign(base, {
    post: post || null,
    validation_passed: outcome === 'validated',
    rule_failures: failures,
    rule_warnings: warnings,
    outcome: outcome === 'validated' ? '' : outcome,
    error_message: msg || '',
  }) }];
}

// 1) Transport/API errors (after the model's own retries) -> retryable failure, never publish.
if (inp.error) {
  const m = typeof inp.error === 'string' ? inp.error : (inp.error.message || JSON.stringify(inp.error));
  return done('generation_failed', 'LLM generation failed after retries: ' + m);
}

// 2) Parse JSON or accept structured model output.
let raw = inp.text;
let out = null;

if (
  inp.status !== undefined &&
  inp.post_text !== undefined &&
  inp.source_url !== undefined
) {
  out = inp;
} else {
  if (raw && typeof raw === 'object') raw = JSON.stringify(raw);
  raw = String(raw == null ? '' : raw)
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/, '')
    .trim();

  try {
    out = JSON.parse(raw);
  } catch (e) {
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) {
      try { out = JSON.parse(m[0]); } catch (e2) { out = null; }
    }
  }
}
if (!out || typeof out !== 'object') {
  failures.push('Model output is not valid JSON.');
  return done('rejected_validation', 'Invalid AI output: not valid JSON. Raw start: ' + raw.slice(0, 120));
}

// 3) Model-declared safe failure.
if (String(out.status || '').toLowerCase() === 'insufficient_source') {
  failures.push('Model reported insufficient source information.');
  return done('insufficient_source', 'Model declined to write a post: ' + String(out.validation_notes || 'insufficient source content'));
}

// 4) Structure checks.
const postText = String(out.post_text || '').trim();
const srcUrl = String(out.source_url || '').trim();
const tags = Array.isArray(out.hashtags) ? out.hashtags.map(String) : [];
if (!postText) failures.push('Missing post_text.');
if (!srcUrl) failures.push('Missing source_url.');
if (!Array.isArray(out.hashtags)) failures.push('hashtags must be an array.');
if (out.validation_notes === undefined) warnings.push('validation_notes missing.');

function norm(u) { return String(u || '').trim().replace(/\/+$/, '').toLowerCase(); }
if (srcUrl && norm(srcUrl) !== norm(src.canonical_url)) failures.push('source_url does not match the selected canonical URL.');

const urlIdx = postText.indexOf(src.canonical_url);
if (postText && urlIdx < 0) failures.push('post_text does not contain the exact source URL.');
const beforeUrl = urlIdx >= 0 ? postText.slice(0, urlIdx) : postText;
if (beforeUrl.length >= MAX) failures.push('Text before the URL is ' + beforeUrl.length + ' characters (limit: under ' + MAX + ').');

const inlineTags = postText.match(/#[A-Za-z0-9_]+/g) || [];

function normalizeHashtag(tag) {
  return String(tag || '').trim().replace(/^#/, '').toLowerCase();
}

const normalizedArrayTags = tags.map(normalizeHashtag);
const normalizedInlineTags = inlineTags.map(normalizeHashtag);

const uniqueArrayTags = [...new Set(normalizedArrayTags)];
const uniqueInlineTags = [...new Set(normalizedInlineTags)];

if (tags.length !== uniqueArrayTags.length) {
  failures.push('Duplicate hashtags found in the hashtags array.');
}

if (inlineTags.length !== uniqueInlineTags.length) {
  failures.push('Duplicate hashtags found in post_text.');
}

if (uniqueInlineTags.length < 3 || uniqueInlineTags.length > 5) {
  failures.push(
    'Inline hashtag count is ' + uniqueInlineTags.length +
    ' (required: 3-5 unique hashtags).'
  );
}

if (
  uniqueArrayTags.length !== uniqueInlineTags.length ||
  uniqueArrayTags.some(tag => !uniqueInlineTags.includes(tag))
) {
  failures.push(
    'The hashtags array does not match the hashtags present in post_text.'
  );
}

const lines = beforeUrl.split(/\n+/).map(function (s) { return s.trim(); }).filter(Boolean);
if (lines.length < 3) warnings.push('Fewer than 3 lines before the URL (expected hook + 2-4 info lines + CTA).');

// 5) Content guardrails against the source text.
const sourceText = [src.title, src.summary, src.page_text].join(' ').toLowerCase();
const body = postText.split(src.canonical_url).join(' ').replace(/#[A-Za-z0-9_]+/g, ' ');

// Always blocked, even if the source uses similar words.
const ALWAYS_BLOCK = [
  [/guarantee[ds]?|guaranteed/i, 'guaranteed outcome'],
  [/\b100\s?%/i, '100% claim'],
  [/risk[- ]free|no risks?\b|zero risk|completely safe/i, 'risk-free / safety guarantee'],
  [/\bmiracle|permanent (results?|cure|fix)/i, 'exaggerated outcome'],
  [/you should (get|have|undergo|book|choose)|is right for you|recommended for you|you need (this|to get|to have)/i, 'personalised medical advice'],
];
// Blocked unless the exact phrase appears in the source.
const NEEDS_SOURCE = [
  [/\bcures?\b|\bcured\b|\bheals?\b|eliminates?|reverses?/i, 'cure / treatment-benefit claim'],
  [/success rates?|recovery rates?/i, 'outcome statistic'],
  [/clinically proven|fda[- ]approved|safe and effective|scientifically proven/i, 'clinical claim'],
  [/(patients?|customers?|clients?) (say|said|love|report|rave)|testimonial|five[- ]star|5[- ]star/i, 'testimonial / review'],
  [/best (doctor|surgeon|clinic|hospital)s?|world[- ]class|top[- ]rated|number one|#1/i, 'unverifiable superlative'],
  [/cheapest|lowest price|save (up to )?[0-9]+/i, 'price / savings claim'],
];
ALWAYS_BLOCK.forEach(function (r) {
  const m = body.match(r[0]);
  if (m) failures.push('Blocked claim (' + r[1] + '): "' + m[0] + '"');
});
NEEDS_SOURCE.forEach(function (r) {
  const m = body.match(r[0]);
  if (m && sourceText.indexOf(m[0].toLowerCase()) < 0) failures.push('Unsupported claim (' + r[1] + '), not found in source: "' + m[0] + '"');
});

// Prices, percentages and multi-digit numbers must appear verbatim in the source.
// Normalize numeric formatting before comparing source and post.
// This reduces false rejections such as 3,000 vs 3000,
// without treating a different number as equivalent.
function normalizeNumberText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/,/g, '')
    .replace(/\s+/g, '')
    .replace(/(?<=\d)\.(?=\d{3}(?:\D|$))/g, '');
}

function extractNormalizedNumbers(value) {
  return (String(value || '').match(/\d+(?:[,.]\d+)*/g) || [])
    .map(normalizeNumberText);
}

const sourceNumbers = new Set(extractNormalizedNumbers(sourceText));
const bodyNumbers = extractNormalizedNumbers(body);

// Prices: compare the numeric value, not a substring.
const normalizedBody = body;
const priceRe = /(?:\$|€|£|\b(?:usd|eur|gbp|aed|inr|pkr|rs\.?)\s?)[0-9][0-9,.]*|[0-9][0-9,.]*\s?(?:usd|eur|gbp|aed|inr|pkr|dollars|euros|pounds)\b/gi;

(normalizedBody.match(priceRe) || []).forEach(function (p) {
  const nums = extractNormalizedNumbers(p);
  if (nums.length && !sourceNumbers.has(nums[0])) {
    failures.push('Price not supported by source: "' + p.trim() + '"');
  }
});

// Percentages: the complete numeric value must match.
(normalizedBody.match(/[0-9][0-9,.]*\s?%/g) || []).forEach(function (p) {
  const nums = extractNormalizedNumbers(p);
  if (nums.length && !sourceNumbers.has(nums[0])) {
    failures.push('Percentage not supported by source: "' + p.trim() + '"');
  }
});

// Multi-digit numbers: compare complete normalized tokens.
bodyNumbers.forEach(function (n) {
  if (n.length >= 2 && !sourceNumbers.has(n)) {
    failures.push('Number not found in source: "' + n + '"');
  }
});

const post = {
  post_text: postText,
  source_url: src.canonical_url,
  hashtags: tags.length ? tags : inlineTags,
  validation_notes: String(out.validation_notes || ''),
  chars_before_url: beforeUrl.length,
};

if (failures.length) {
  return done('rejected_validation', 'Rule validation failed: ' + failures.join(' | '), post);
}
return done('validated', '', post);

