 // Interprets the second-LLM safety review.
// Anything other than explicit "approve" blocks progression.
const draft = $('Parse & Validate Post').first().json;
const inp = $input.first().json || {};

let verdict = 'uncertain';
let issues = [];
let err = '';

if (inp.error) {
  err = typeof inp.error === 'string'
    ? inp.error
    : (inp.error.message || JSON.stringify(inp.error));
} else {
  let out = null;

  // Accept a directly structured review response.
  if (inp.verdict !== undefined) {
    out = inp;
  } else {
    let raw =
      inp.text ??
      inp.response?.generations?.[0]?.[0]?.text ??
      inp.output ??
      '';

    if (raw && typeof raw === 'object') {
      raw = JSON.stringify(raw);
    }

    raw = String(raw == null ? '' : raw)
      .trim()
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/```\s*$/, '')
      .trim();

    try {
      out = JSON.parse(raw);
    } catch (e) {
      const m = raw.match(/\{[\s\S]*\}/);
      if (m) {
        try {
          out = JSON.parse(m[0]);
        } catch (e2) {
          out = null;
        }
      }
    }
  }

  if (out && typeof out === 'object') {
    verdict = String(out.verdict || 'uncertain')
      .toLowerCase()
      .trim();

    issues = []
      .concat(out.issues || [], out.unsupported_claims || [])
      .map(String);
  } else {
    issues = ['Review output was not valid JSON.'];
  }
}

const ok = !err && verdict === 'approve';

return [{
  json: Object.assign({}, draft, {
    review_status: err ? 'review_error' : verdict,
    review_issues: issues,
    final_ok: ok,
    outcome: ok ? '' : (err ? 'review_failed' : 'rejected_llm_review'),
    error_message: ok
      ? ''
      : (err
          ? 'LLM safety review failed after retries: ' + err
          : 'LLM safety review verdict "' + verdict + '": ' +
            (issues.join('; ') || 'no details'))
  })
}];

// Classifies the publish result (real or simulated). Never retries a publish:
// a timed-out POST may still have created the post, so failures go to a human.
const p = $input.first().json || {};
// Non-approval results (reject / timeout / notification failure) pass straight through.
if (p.outcome) {
  return [{ json: { outcome: p.outcome, facebook_post_id: '', error_message: String(p.error_message || ''), simulated: false, publish_edge: '' } }];
}
let outcome = '';
let fbId = '';
let err = '';

if (p.config_error) {
  outcome = 'config_error';
  err = String(p.error_message || 'Invalid publishing configuration.');
} else if (p.error) {
  const e = typeof p.error === 'object' ? p.error : { message: String(p.error) };
  const blob = JSON.stringify(p.error) + ' ' + String(p.description || '');
  err = String(e.message || blob).slice(0, 500);
  const m = blob.match(/#([0-9]+)/);
  const code = Number(e.code || (m ? m[1] : 0));
  const isAuth = [190, 102, 10, 200, 463, 467].indexOf(code) >= 0 || /oauth|access token|session has expired|token|permission/i.test(blob);
  outcome = isAuth ? 'auth_error' : 'publish_failed';
} else if (p.post_id || p.id) {
  fbId = String(p.post_id || p.id);
  outcome = p.simulated ? 'dry_run_ok' : 'published';
} else {
  outcome = 'publish_failed';
  err = 'Facebook returned no post ID: ' + JSON.stringify(p).slice(0, 300);
}

return [{ json: {
  outcome: outcome,
  facebook_post_id: fbId,
  error_message: err,
  simulated: !!p.simulated,
  publish_edge: p.would_use_edge || '',
} }];

// ============================================================
// SIMULATED FACEBOOK RESPONSE — TEST ONLY. No request is sent to Facebook.
// Used whenever FACEBOOK_DRY_RUN = true or the item is mock test data.
// ============================================================
const cfg = $('Workflow Config').first().json;
const scenario = String(cfg.TEST_SCENARIO || 'valid_source_item');
const p = $json;
const edge = p.has_image ? 'photos' : 'feed';

if (scenario === 'expired_token') {
  return [{ json: { simulated: true, would_use_edge: edge, error: { message: '(#190) Error validating access token: Session has expired. [SIMULATED]', type: 'OAuthException', code: 190 } } }];
}
if (scenario === 'publishing_failure') {
  return [{ json: { simulated: true, would_use_edge: edge, error: { message: '(#368) The action attempted has been deemed abusive or is otherwise disallowed. [SIMULATED]', code: 368 } } }];
}
const fakeId = 'DRYRUN_' + String($execution.id || 'manual');
return [{ json: { simulated: true, would_use_edge: edge, id: fakeId, post_id: fakeId, message_preview: String(p.message || '').slice(0, 200), image_url: p.image_url || '' } }];
